/* Arabic (UAE) for the app layer. Brand names, codes and flight numbers stay as written.
   Needs a native review before launch; the wording follows the kit's Arabic pack. */

const CITY: Record<string, string> = { Dubai: 'دبي', Muscat: 'مسقط', London: 'لندن', Istanbul: 'إسطنبول', 'Malé': 'ماليه', Bangkok: 'بانكوك' }
const COUNTRY: Record<string, string> = { Oman: 'عُمان', UK: 'المملكة المتحدة', 'Türkiye': 'تركيا', Maldives: 'جزر المالديف', Thailand: 'تايلاند', UAE: 'الإمارات' }
const c = (s: string) => CITY[s] || s
const MON: Record<string, string> = { Jan: 'يناير', Feb: 'فبراير', Mar: 'مارس', Apr: 'أبريل', May: 'مايو', Jun: 'يونيو', Jul: 'يوليو', Aug: 'أغسطس', Sep: 'سبتمبر', Oct: 'أكتوبر', Nov: 'نوفمبر', Dec: 'ديسمبر' }
const DAY: Record<string, string> = { Mon: 'الاثنين', Tue: 'الثلاثاء', Wed: 'الأربعاء', Thu: 'الخميس', Fri: 'الجمعة', Sat: 'السبت', Sun: 'الأحد' }
const d = (s: string) => s.replace(/\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b/g, x => DAY[x]).replace(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b/g, x => MON[x])

/** Arabic counting: 1, 2, 3 to 10, 11 and up take different forms. */
export function cnt(nIn: string | number, one: string, two: string, few: string, many: string) {
  const n = +String(nIn).replace(/[^0-9]/g, '')
  if (n === 1) return one
  if (n === 2) return two
  return `${nIn} ${n % 100 >= 3 && n % 100 <= 10 ? few : many}`
}
const DAYS = (n: string) => cnt(n, 'يوم واحد', 'يومان', 'أيام', 'يومًا')
const VISITS = (n: string) => cnt(n, 'زيارة واحدة', 'زيارتان', 'زيارات', 'زيارة')
const NIGHTSA = (n: string) => cnt(n, 'ليلة واحدة', 'ليلتين', 'ليالٍ', 'ليلة')
const FREEV = (n: string) => cnt(n, 'زيارة مجانية واحدة', 'زيارتان مجانيتان', 'زيارات مجانية', 'زيارة مجانية')
const PEOPLE = (n: string) => cnt(n, 'شخص واحد', 'شخصان', 'أشخاص', 'شخصًا')
const MINS = (n: string) => cnt(n, 'دقيقة واحدة', 'دقيقتان', 'دقائق', 'دقيقة')
const FLIGHTS = (n: string) => cnt(n, 'رحلة واحدة', 'رحلتان', 'رحلات', 'رحلة')
const DAYSG = (n: string) => cnt(n, 'يوم واحد', 'يومين', 'أيام', 'يومًا')
const NIGHTS = (n: string) => cnt(n, 'ليلة واحدة', 'ليلتان', 'ليالٍ', 'ليلة')
const forPeople = (n: string) => (+n === 1 ? 'لشخص واحد' : +n === 2 ? 'لشخصين' : `لـ ${n} ${+n <= 10 ? 'أشخاص' : 'شخصًا'}`)
